/**
 * ConversationSpec
 *
 * What a new call knows about earlier ones with the same person.
 */
export type ConversationSpec = {
    /**
     * Context
     *
     * How much of the past comes into a new call: 'none' starts clean, 'summary' adds background on recent conversations, 'transcript' carries the same conversation on. Set on the agent that answers. A WhatsApp call always carries the chat on.
     */
    context?: 'none' | 'summary' | 'transcript';
    /**
     * Initialize Userdata
     *
     * Start the call already knowing what the agent learned about this person on earlier ones. Used by 'summary' and 'transcript' only; a 'none' call always starts empty.
     */
    initialize_userdata?: boolean;
    /**
     * Summary Limit
     *
     * How many recent calls to summarize. Leave empty for all of them. Used by 'summary' only.
     */
    summary_limit?: number | null;
};

/**
 * ConversationSpecOverride
 *
 * A partial ConversationSpec: only the fields this call changes. Absent keeps the base value, an explicit null clears it, objects deep-merge and lists replace.
 */
export type ConversationSpecOverride = {
    /**
     * Context
     *
     * How much of the past comes into a new call: 'none' starts clean, 'summary' adds background on recent conversations, 'transcript' carries the same conversation on. Set on the agent that answers. A WhatsApp call always carries the chat on.
     */
    context?: 'none' | 'summary' | 'transcript' | null;
    /**
     * Initialize Userdata
     *
     * Start the call already knowing what the agent learned about this person on earlier ones. Used by 'summary' and 'transcript' only; a 'none' call always starts empty.
     */
    initialize_userdata?: boolean | null;
    /**
     * Summary Limit
     *
     * How many recent calls to summarize. Leave empty for all of them. Used by 'summary' only.
     */
    summary_limit?: number | null;
};

