export type ConversationsEventsResults = {
    /**
     * Response 200 Conversations.Events
     *
     * A `text/event-stream` that stays open. Each frame is `event: <name>` followed by `data: <json>`, and the JSON repeats the name in its `event` field so one value identifies the frame. A line starting `:` is a keep-alive, sent every 15s so idle proxies do not close the connection. Read it with an SSE client (`EventSource`, `httpx-sse`) — the body is never a single JSON document.
     */
    200: ({
        event: 'conversation.snapshot';
    } & ConversationSnapshotEvent) | ({
        event: 'item.created';
    } & ItemCreatedEvent) | ({
        event: 'item.delivery_updated';
    } & ItemDeliveryUpdatedEvent) | ({
        event: 'turn';
    } & TurnPayload) | ({
        event: 'turn.failed';
    } & TurnFailedEvent) | ({
        event: 'assistant.started';
    } & AssistantStartedEvent) | ({
        event: 'assistant.delta';
    } & AssistantDeltaEvent) | ({
        event: 'assistant.completed';
    } & AssistantCompletedEvent);
};

export type ConversationsEventsResult = ConversationsEventsResults[keyof ConversationsEventsResults];

